    }
  ],
  "task_complete": false
}

{
  "analysis": "QEMU (pid 159) is running under TCG and the serial console is listening on 127.0.0.1:9001 (nc connected successfully). Now I need to let Alpine boot and drive the serial console to: set root password, configure network via DHCP, install/start openssh, and permit root password login. I'll do this with an expect script that connects to the serial console over nc.",
  "plan": "Write /app/setup.exp that: connects to the serial console via nc, logs in as root, brings up eth0 + udhcpc, sets password to password123, installs openssh, generates host keys, fixes sshd_config for root+password login, and starts sshd. Then run it (with a long timeout for apk). After it finishes, verify the host is listening on 2222 and test an actual ssh login.",
  "commands": [
    {
      "keystrokes": "cat > /app/setup.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 240

proc cmd {c} {
    send "$c\r"
    expect {
        "# " {}
        timeout { puts "TIMEOUT_CMD: $c"; exit 2 }
    }
}

spawn nc 127.0.0.1 9001
sleep 1
send "\r"
expect {
    "login:" {
        send "root\r"
        expect {
            "Password:" { send "\r" }
            "# " {}
            timeout { puts "TIMEOUT_AFTER_LOGIN"; exit 1 }
        }
    }
    "# " {}
    timeout { puts "TIMEOUT_WAITING"; exit 1 }
}

cmd "ip link set eth0 up"
cmd "udhcpc -i eth0"
cmd "echo root:password123 | chpasswd"
cmd "apk add openssh"
cmd "ssh-keygen -A"
cmd "sed -i 's/^#\\?PermitRootLogin.*/PermitRootLogin yes/ ; s/^#\\?PasswordAuthentication.*/PasswordAuthentication yes/' /etc/ssh/sshd_config"
cmd "/usr/sbin/sshd"
cmd "echo SETUP_DONE_OK"
expect "SETUP_DONE_OK"
send "exit\r"
EOF
",
      "duration": 0.2
    },
    {
      "keystrokes": "expect /app/setup.exp
